using UnityEditor; using UnityEditor.SceneManagement; using UnityEngine;
namespace DungeonRoguelite.Editor { [InitializeOnLoad] public static class D5CompletionOrderingRunner { static D5CompletionOrderingRunner(){EditorApplication.playModeStateChanged+=s=>{if(s==PlayModeStateChange.EnteredPlayMode&&SessionState.GetBool("D5Order",false)){SessionState.EraseBool("D5Order");new GameObject("D5CompletionOrderingVerifier").AddComponent<Tests.D5CompletionOrderingVerifier>();}};if(!EditorApplication.isPlayingOrWillChangePlaymode&&System.Array.IndexOf(System.Environment.GetCommandLineArgs(),"-runD5CompletionOrdering")>=0)EditorApplication.delayCall+=Run;} static void Run(){EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);SessionState.SetBool("D5Order",true);EditorApplication.EnterPlaymode();}} }
